import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"多模态应用入门","description":"多模态模型能直接理解图像、音频和视频，但要算清 token、认清边界，才知道何时该用、何时别用。","frontmatter":{"title":"多模态应用入门","description":"多模态模型能直接理解图像、音频和视频，但要算清 token、认清边界，才知道何时该用、何时别用。"},"headers":[],"relativePath":"ai/multimodal.md","filePath":"ai/multimodal.md","lastUpdated":1786271684000}'),l={name:"ai/multimodal.md"};function o(i,t,d,r,p,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="多模态应用入门" tabindex="-1">多模态应用入门 <a class="header-anchor" href="#多模态应用入门" aria-label="Permalink to &quot;多模态应用入门&quot;">​</a></h1><p>过去 LLM 只吃文本，看不懂图、听不懂语音。多模态模型把图像、音频、视频也变成输入，让应用能&quot;看&quot;和&quot;听&quot;：识别一张发票、理解一张图表、给视频生成字幕、审核图片是否违规。但多模态不是万能的——它贵、慢、在细节精确性上有明显边界。理解它的能力范围和成本结构，才能判断一个需求到底该不该用多模态。</p><h2 id="多模态模型能做什么" tabindex="-1">多模态模型能做什么 <a class="header-anchor" href="#多模态模型能做什么" aria-label="Permalink to &quot;多模态模型能做什么&quot;">​</a></h2><p>主流多模态模型（GPT-4o、Gemini、Claude 等）能直接接收非文本输入并理解其内容：</p><table tabindex="0"><thead><tr><th>能力</th><th>典型场景</th></tr></thead><tbody><tr><td>图像理解</td><td>OCR、物体识别、图表解读、UI 截图还原、内容审核</td></tr><tr><td>音频理解</td><td>语音转写、说话人区分、情感识别、会议纪要</td></tr><tr><td>视频理解</td><td>关键帧分析、动作识别、视频字幕、违规检测</td></tr><tr><td>文档理解</td><td>扫描件、PDF、含图表的论文结构化抽取</td></tr></tbody></table><p>和纯文本模型的核心区别：纯文本模型需要你先把图 OCR 成文字、把音频转成文字，它才能处理，中间这一步错了后面全错。多模态模型跳过了这个中间表示，直接&quot;看图说话&quot;，因此在排版复杂的文档、含图表的资料上，效果往往优于&quot;OCR + 文本模型&quot;的串联方案。</p><h2 id="与纯文本应用的关键差异" tabindex="-1">与纯文本应用的关键差异 <a class="header-anchor" href="#与纯文本应用的关键差异" aria-label="Permalink to &quot;与纯文本应用的关键差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>纯文本</th><th>多模态</th></tr></thead><tbody><tr><td>输入体积</td><td>几 KB</td><td>单张图几 MB，视频更大</td></tr><tr><td>Token 计算</td><td>按字符/词</td><td>图像按分辨率切块折算，音频按时长</td></tr><tr><td>延迟</td><td>低</td><td>显著更高（编码耗时）</td></tr><tr><td>成本</td><td>低</td><td>高，且随分辨率/时长线性涨</td></tr><tr><td>可靠性</td><td>文本明确</td><td>细节易出错（小字、密集表格、计数）</td></tr></tbody></table><p>最大坑在于 <strong>token 计算方式和成本</strong>。一张高分辨率图片，折算成 token 可能是几千甚至上万，远超一段长文本。如果不做尺寸压缩和裁剪，一次对话烧掉的成本可能超出预期一个数量级。</p><h2 id="token-与成本怎么算" tabindex="-1">Token 与成本怎么算 <a class="header-anchor" href="#token-与成本怎么算" aria-label="Permalink to &quot;Token 与成本怎么算&quot;">​</a></h2><p>不同厂商的折算规则不同，但思路一致：把图像切成若干 tile，每个 tile 按固定 token 计。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以某模型为例（近似）：</span></span>
<span class="line"><span>  - 一张 1024x1024 图 ≈ 765 tokens</span></span>
<span class="line"><span>  - 一张 4K 高清图 ≈ 3000+ tokens</span></span>
<span class="line"><span>  - 1 分钟音频 ≈ 几百到上千 tokens</span></span>
<span class="line"><span>  - 1 分钟视频（抽帧）≈ 数千 tokens</span></span></code></pre></div><p>务实做法：<strong>进模型前先预处理</strong>。图片按需缩放裁剪到模型最佳分辨率（通常 1024~1568 边长就够了）；视频只抽关键帧而不是逐帧；音频先做 VAD 切掉静音段。这不仅省钱，也降延迟。</p><h2 id="典型应用场景" tabindex="-1">典型应用场景 <a class="header-anchor" href="#典型应用场景" aria-label="Permalink to &quot;典型应用场景&quot;">​</a></h2><ul><li><strong>OCR 与结构化抽取</strong>：发票、合同、表单转 JSON。多模态对复杂版式优于纯 OCR。</li><li><strong>图表理解</strong>：让模型读出柱状图/折线图的数值和趋势，做数据分析问答。</li><li><strong>内容审核</strong>：判断图片是否含违禁内容，作为 Guardrails 的一环。</li><li><strong>描述生成</strong>：给商品图生成营销文案、给无障碍场景生成图片描述。</li><li><strong>UI 与代码</strong>：截图还原成前端代码、设计稿转页面。</li></ul><blockquote><p>对&quot;精确计数&quot;和&quot;密集小字&quot;要格外小心。模型经常数错&quot;图里有几个人&quot;、读错表格里的小数字。这类需求要么用专门的传统算法兜底，要么限定输入复杂度。</p></blockquote><h2 id="限制与边界" tabindex="-1">限制与边界 <a class="header-anchor" href="#限制与边界" aria-label="Permalink to &quot;限制与边界&quot;">​</a></h2><p>多模态模型不是&quot;看得清一切&quot;。它常见的失败模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 细粒度计数：数错密集物体（人群、商品）</span></span>
<span class="line"><span>- 精确文字：手写体、艺术字、小字号易认错</span></span>
<span class="line"><span>- 空间关系：左右、前后判断有时会混乱</span></span>
<span class="line"><span>- 时间序列：视频里动作发生的先后顺序容易记错</span></span>
<span class="line"><span>- 幻觉：凭空描述图中没有的东西，且很自信</span></span></code></pre></div><p>边界处理原则：<strong>能用专门的、确定性的工具解决，就不要用多模态硬扛</strong>。比如纯文字识别用 OCR 引擎更稳更便宜；人脸核身用专用模型；只有那些&quot;需要理解语义、版式灵活、文本方案搞不定&quot;的场景，才值得上多模态。</p><h2 id="什么时候不该用多模态" tabindex="-1">什么时候不该用多模态 <a class="header-anchor" href="#什么时候不该用多模态" aria-label="Permalink to &quot;什么时候不该用多模态&quot;">​</a></h2><ul><li>需求本质是纯文本处理（文档已经是可复制文字的 PDF），OCR 一次再喂文本模型更省。</li><li>要求 100% 精确的计数或数值核对，模型概率性输出兜不住。</li><li>实时性要求极高（&lt;200ms），多模态编码延迟满足不了。</li><li>成本敏感且流量大，每张图都过模型会烧钱。</li></ul><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>输入是否做过预处理（缩放、裁剪、抽帧、去静音）以控制 token 和成本？</li><li>是否清楚目标模型的 token 折算规则，估过单次调用的费用？</li><li>对精确性要求高的字段（数字、计数、小字）有没有传统方案兜底或人工校验？</li><li>场景是否真的需要&quot;理解语义&quot;，还是传统 OCR/CV 方案更稳更便宜？</li><li>失败时是否有降级路径（识别失败 → 提示用户手动输入）？</li><li>是否监控了延迟和成本，避免线上流量把账单打爆？</li></ul>`,24)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
